import{_ as a,c as e,o as n,a0 as t}from"./chunks/framework.DKRgXLPU.js";const r=JSON.parse('{"title":"Introduktion till mentalspelet - Presentationsbilder för handledaren","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/sv/facilitator-slides.md","filePath":"public/downloads/sv/facilitator-slides.md"}');const i=a({name:"public/downloads/sv/facilitator-slides.md"},[["render",function(a,r,i,l,s,o){return n(),e("div",null,[...r[0]||(r[0]=[t('<h1 id="introduktion-till-mentalspelet-presentationsbilder-for-handledaren" tabindex="-1">Introduktion till mentalspelet - Presentationsbilder för handledaren <a class="header-anchor" href="#introduktion-till-mentalspelet-presentationsbilder-for-handledaren" aria-label="Permalink to &quot;Introduktion till mentalspelet - Presentationsbilder för handledaren&quot;">​</a></h1><p><strong>Petanque Academy</strong><em>Sessionsguide för handledare</em></p><hr><h2 id="bild-1-valkommen" tabindex="-1">Bild 1: Välkommen <a class="header-anchor" href="#bild-1-valkommen" aria-label="Permalink to &quot;Bild 1: Välkommen&quot;">​</a></h2><h1 id="🎯-introduktion-till-mentala-spel" tabindex="-1">🎯 Introduktion till mentala spel <a class="header-anchor" href="#🎯-introduktion-till-mentala-spel" aria-label="Permalink to &quot;🎯 Introduktion till mentala spel&quot;">​</a></h1><p><strong>För Elite Petanque-spelare</strong></p><h3 id="idag-kommer-du-att-upptacka" tabindex="-1">Idag kommer du att upptäcka: <a class="header-anchor" href="#idag-kommer-du-att-upptacka" aria-label="Permalink to &quot;Idag kommer du att upptäcka:&quot;">​</a></h3><ul><li>🧠 Hur man skapar rätt förutsättningar för &quot;zonen&quot;</li><li>💪 Hur du tystar din inre kritiker</li><li>🎪 Praktiska verktyg som fungerar under press</li></ul><p><strong>Gör dig redo för en interaktiv session!</strong></p><hr><h2 id="bild-2-snabb-omrostning-handupprackning-🙋" tabindex="-1">Bild 2: Snabb omröstning - Handuppräckning! 🙋 <a class="header-anchor" href="#bild-2-snabb-omrostning-handupprackning-🙋" aria-label="Permalink to &quot;Bild 2: Snabb omröstning - Handuppräckning! 🙋&quot;">​</a></h2><h3 id="vem-har-upplevt-detta" tabindex="-1">Vem har upplevt detta? <a class="header-anchor" href="#vem-har-upplevt-detta" aria-label="Permalink to &quot;Vem har upplevt detta?&quot;">​</a></h3><p><strong>Räck upp handen om du någonsin har:</strong></p><ol><li><p>Gjorde ett perfekt skott på träningen... och missade det sedan på tävlingen? 🎯❌</p></li><li><p>Kände du att dina tankar rusade iväg när du behövde hålla dig lugn? 🧠💨</p></li><li><p>Kritiserade du dig själv efter ett misstag? 😤</p></li><li><p>Hade du ett spel där allt bara &quot;klickade&quot;? ✨</p></li></ol><p><strong>Du är inte ensam! Låt oss fixa det här tillsammans.</strong></p><hr><h2 id="bild-3-elitspelarens-paradox" tabindex="-1">Bild 3: Elitspelarens paradox <a class="header-anchor" href="#bild-3-elitspelarens-paradox" aria-label="Permalink to &quot;Bild 3: Elitspelarens paradox&quot;">​</a></h2><h3 id="du-har-redan-fardigheterna-sa-varfor" tabindex="-1">Du har redan färdigheterna... så varför? <a class="header-anchor" href="#du-har-redan-fardigheterna-sa-varfor" aria-label="Permalink to &quot;Du har redan färdigheterna... så varför?&quot;">​</a></h3><p><strong>✅ Du HAR:</strong></p><ul><li>Utmärkt teknik (tusentals timmar)</li><li>Åratals erfarenhet</li><li>Fysisk förmåga</li></ul><p><strong>❌ Men du KÄMPAR med:</strong></p><ul><li>Att få tillgång till den tekniken under press</li><li>Att vara konsekvent i tävlingen</li><li>Att komma tillbaka efter misstag</li></ul><h3 id="den-saknade-biten-🧩" tabindex="-1">Den saknade biten? 🧩 <a class="header-anchor" href="#den-saknade-biten-🧩" aria-label="Permalink to &quot;Den saknade biten? 🧩&quot;">​</a></h3><p><strong>Ditt mentala spel.</strong></p><p><em>&quot;Skillnaden mellan bra och stor är vad som händer mellan dina öron.&quot;</em></p><hr><h2 id="bild-4-zonen-du-kanner-igen-den-har-kanslan-⚡" tabindex="-1">Bild 4: Zonen - Du känner igen den här känslan! ⚡ <a class="header-anchor" href="#bild-4-zonen-du-kanner-igen-den-har-kanslan-⚡" aria-label="Permalink to &quot;Bild 4: Zonen - Du känner igen den här känslan! ⚡&quot;">​</a></h2><h3 id="kommer-du-ihag-det-perfekta-spelet" tabindex="-1">Kommer du ihåg det perfekta spelet? <a class="header-anchor" href="#kommer-du-ihag-det-perfekta-spelet" aria-label="Permalink to &quot;Kommer du ihåg det perfekta spelet?&quot;">​</a></h3><p><strong>Allt kändes:</strong></p><ul><li>⏱️ Tiden saktade ner</li><li>🎯 Enkelt och automatiskt</li><li>🧘 Helt fokuserad</li><li>🎪 Som om du inte kunde missa</li></ul><h3 id="det-ar-quot-zonen-quot-flodestillstandet" tabindex="-1">Det är &quot;Zonen&quot; (Flödestillståndet) <a class="header-anchor" href="#det-ar-quot-zonen-quot-flodestillstandet" aria-label="Permalink to &quot;Det är &amp;quot;Zonen&amp;quot; (Flödestillståndet)&quot;">​</a></h3><p><strong>Frågan:</strong><em>Hur får vi tillgång till det konsekvent, inte bara av misstag?</em></p><p><strong>Svaret:</strong><em>Förstår dina två tankesätt...</em></p><hr><h2 id="bild-5-din-hjarna-har-tva-lagen-🧠" tabindex="-1">Bild 5: Din hjärna har två lägen 🧠 <a class="header-anchor" href="#bild-5-din-hjarna-har-tva-lagen-🧠" aria-label="Permalink to &quot;Bild 5: Din hjärna har två lägen 🧠&quot;">​</a></h2><h3 id="🤔-planeringslage-analytisk-hjarna" tabindex="-1">🤔 PLANERINGSLÄGE (Analytisk hjärna) <a class="header-anchor" href="#🤔-planeringslage-analytisk-hjarna" aria-label="Permalink to &quot;🤔 PLANERINGSLÄGE (Analytisk hjärna)&quot;">​</a></h3><p><strong>När ska det användas:</strong> FÖRE injektionen</p><ul><li>📊 Analysera terrängen</li><li>🎯 Att välja din strategi</li><li>⚖️ Att väga riskerna</li><li>🤝 Bestäm skottet</li></ul><h3 id="🎯-utforingslage-flow-brain" tabindex="-1">🎯 UTFÖRINGSLÄGE (Flow Brain) <a class="header-anchor" href="#🎯-utforingslage-flow-brain" aria-label="Permalink to &quot;🎯 UTFÖRINGSLÄGE (Flow Brain)&quot;">​</a></h3><p><strong>När ska det användas:</strong> UNDER injektionen</p><ul><li>💪 Lita på din kropp</li><li>🚫 Tänker INTE på teknik</li><li>⏰ Endast nuet</li><li>🤖 Automatisk prestanda</li></ul><h3 id="⚠️-problemet" tabindex="-1">⚠️ PROBLEMET: <a class="header-anchor" href="#⚠️-problemet" aria-label="Permalink to &quot;⚠️ PROBLEMET:&quot;">​</a></h3><p><strong>De flesta spelare stannar i planeringsläge under körningen!</strong><em>Din analytiska hjärna stör din automatiska prestation.</em></p><hr><h2 id="bild-6-vaxeln-ditt-hemliga-vapen-🔄" tabindex="-1">Bild 6: Växeln - Ditt hemliga vapen 🔄 <a class="header-anchor" href="#bild-6-vaxeln-ditt-hemliga-vapen-🔄" aria-label="Permalink to &quot;Bild 6: Växeln - Ditt hemliga vapen 🔄&quot;">​</a></h2><h3 id="bemastra-denna-fardighet" tabindex="-1">Bemästra denna färdighet: <a class="header-anchor" href="#bemastra-denna-fardighet" aria-label="Permalink to &quot;Bemästra denna färdighet:&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BEFORE the shot:          DURING the shot:</span></span>\n<span class="line"><span>🤔 Planning Mode    →     🎯 Execution Mode</span></span></code></pre></div><h3 id="processen" tabindex="-1">Processen: <a class="header-anchor" href="#processen" aria-label="Permalink to &quot;Processen:&quot;">​</a></h3><p><strong>1️⃣ FÖRE (10–15 sekunder):</strong></p><ul><li>🤔 Analysera allt</li><li>📊 Planera din strategi</li><li>✅ Ta ditt beslut</li></ul><p><strong>2️⃣ BYTET (3 andetag):</strong></p><ul><li>🌬️ Andas djupt</li><li>🧘 Rensa dina tankar</li><li>🔄 Släpp analysen</li></ul><p><strong>3️⃣ UNDER (2–3 sekunder):</strong></p><ul><li>🎯 Lita helt och hållet på</li><li>🤖 Låt det hända</li><li>⚡ Kör automatiskt</li></ul><p><strong>Öva på denna växling = Åtkomstflöde på begäran!</strong></p><hr><h2 id="bild-7-aktivitet-prova-nu-🎯" tabindex="-1">Bild 7: AKTIVITET - Prova nu! 🎯 <a class="header-anchor" href="#bild-7-aktivitet-prova-nu-🎯" aria-label="Permalink to &quot;Bild 7: AKTIVITET - Prova nu! 🎯&quot;">​</a></h2><h3 id="lat-oss-ova-pa-vaxlingen-2-minuter" tabindex="-1">Låt oss öva på växlingen (2 minuter) <a class="header-anchor" href="#lat-oss-ova-pa-vaxlingen-2-minuter" aria-label="Permalink to &quot;Låt oss öva på växlingen (2 minuter)&quot;">​</a></h3><p><strong>Alla reser sig upp!</strong></p><ol><li><p><strong>Planeringsläge (10 sek):</strong> Tänk dig att analysera ett skott. Tänk på terräng, strategi och risker.</p></li><li><p><strong>Brytaren (3 andetag):</strong> Ta 3 djupa andetag. Rensa dina tankar med varje utandning.</p></li><li><p><strong>Utförandeläge (3 sek):</strong> Tänk dig att kasta. Inget tänkande. Bara lita på och flyta.</p></li></ol><p><strong>Hur kändes det? Annorlunda?</strong></p><p><em>Sätt er ner så diskuterar vi...</em></p><hr><h2 id="bild-8-mot-din-inre-kritiker-😈" tabindex="-1">Bild 8: Möt din inre kritiker 😈 <a class="header-anchor" href="#bild-8-mot-din-inre-kritiker-😈" aria-label="Permalink to &quot;Bild 8: Möt din inre kritiker 😈&quot;">​</a></h2><h3 id="later-den-har-rosten-bekant" tabindex="-1">Låter den här rösten bekant? <a class="header-anchor" href="#later-den-har-rosten-bekant" aria-label="Permalink to &quot;Låter den här rösten bekant?&quot;">​</a></h3><p><strong>Efter ett dåligt skott:</strong></p><ul><li>💢 &quot;Det var HEMSKT!&quot;</li><li>😤 &quot;Du gör ALLTID fel under press!&quot;</li><li>😰 &quot;Alla ser dig misslyckas!&quot;</li><li>😞 &quot;Du är helt enkelt inte tillräckligt bra!&quot;</li></ul><h3 id="snabb-omrostning-🙋" tabindex="-1">Snabb omröstning: 🙋 <a class="header-anchor" href="#snabb-omrostning-🙋" aria-label="Permalink to &quot;Snabb omröstning: 🙋&quot;">​</a></h3><p><strong>Vem hör den här rösten regelbundet?</strong></p><h3 id="sanningen" tabindex="-1">Sanningen: <a class="header-anchor" href="#sanningen" aria-label="Permalink to &quot;Sanningen:&quot;">​</a></h3><p><strong>Din inre kritiker försöker hjälpa dig...</strong><em>Men det förstör faktiskt din prestation.</em></p><hr><h2 id="bild-9-avskeda-din-kritiker-anstall-din-coach-🔄" tabindex="-1">Bild 9: Avskeda din kritiker, anställ din coach! 🔄 <a class="header-anchor" href="#bild-9-avskeda-din-kritiker-anstall-din-coach-🔄" aria-label="Permalink to &quot;Bild 9: Avskeda din kritiker, anställ din coach! 🔄&quot;">​</a></h2><h3 id="forvandlingen" tabindex="-1">Förvandlingen: <a class="header-anchor" href="#forvandlingen" aria-label="Permalink to &quot;Förvandlingen:&quot;">​</a></h3><p>| 😈 Inre kritiker | ➡️ | 😊 Inre coach | |---------------| ...| | &quot;Du gör ALLTID fel!&quot; | → | &quot;Jag har gjort den här bilden 1000 gånger förut&quot; | | &quot;Det där var FRUKTANSVÄRT!&quot; | → | &quot;Vad kan jag lära mig av det här?&quot; | | &quot;Alla dömer dig!&quot; | → | &quot;Fokusera på MITT spel, inte deras åsikter&quot; | | &quot;Du är inte tillräckligt bra!&quot; | → | &quot;Jag förbättras varje dag&quot; |</p><h3 id="effekten" tabindex="-1">Effekten: <a class="header-anchor" href="#effekten" aria-label="Permalink to &quot;Effekten:&quot;">​</a></h3><p><strong>Kritiker = Ångest, spänning, dålig prestation</strong><strong>Coach = Självförtroende, avslappning, topprestationer</strong></p><hr><h2 id="bild-10-aktivitet-omformulera-din-kritiker-💬" tabindex="-1">Bild 10: AKTIVITET - Omformulera din kritiker! 💬 <a class="header-anchor" href="#bild-10-aktivitet-omformulera-din-kritiker-💬" aria-label="Permalink to &quot;Bild 10: AKTIVITET - Omformulera din kritiker! 💬&quot;">​</a></h2><h3 id="partnerovning-3-minuter" tabindex="-1">Partnerövning (3 minuter) <a class="header-anchor" href="#partnerovning-3-minuter" aria-label="Permalink to &quot;Partnerövning (3 minuter)&quot;">​</a></h3><p><strong>Vänd dig till personen bredvid dig:</strong></p><p><strong>Person A (1,5 min):</strong></p><ol><li>Dela en sak som din inre kritiker säger</li><li>Partnern hjälper dig att omformulera det som Inre Coach</li><li>Skriv ner den nya frasen</li></ol><p><strong>Person B (1,5 min):</strong></p><ol><li>Samma process</li><li>Dela din inre kritikertanke</li><li>Få hjälp med att omformulera det</li></ol><p><strong>Klar? Kör!</strong></p><p><em>Vi kommer att dela några exempel med gruppen efteråt...</em></p><hr><h2 id="bild-11-verktyg-1-3-andetagsaterstallning-🌬️" tabindex="-1">Bild 11: Verktyg #1 - 3-andetagsåterställning 🌬️ <a class="header-anchor" href="#bild-11-verktyg-1-3-andetagsaterstallning-🌬️" aria-label="Permalink to &quot;Bild 11: Verktyg #1 - 3-andetagsåterställning 🌬️&quot;">​</a></h2><h3 id="din-nodtrycksventil" tabindex="-1">Din nödtrycksventil <a class="header-anchor" href="#din-nodtrycksventil" aria-label="Permalink to &quot;Din nödtrycksventil&quot;">​</a></h3><p><strong>Använd detta när:</strong></p><ul><li>😤 Du gjorde just ett misstag</li><li>😰 Du känner att pressen ökar</li><li>🤯 Dina tankar rusar</li></ul><h3 id="processen-1" tabindex="-1">Processen: <a class="header-anchor" href="#processen-1" aria-label="Permalink to &quot;Processen:&quot;">​</a></h3><p><strong>🌬️ ANDNING 1 (Andas in 4 sek):</strong> Lägg märke till var du känner spänning (axlar? käke? mage?)</p><p><strong>🌬️ ANDNING 2 (Andas ut 6 sek):</strong> Släpp spänningen. Låt den flöda ut med din andning.</p><p><strong>🌬️ ANDNING 3 (Inandning 4, Utandning 6):</strong> Fokusera på NU. Den här bilden. Det här ögonblicket. Inget annat.</p><p><strong>⏱️ Tar 20 sekunder. Förändrar allt.</strong></p><hr><h2 id="bild-12-demo-testa-det-allihopa-🌬️" tabindex="-1">Bild 12: DEMO - Testa det allihopa! 🌬️ <a class="header-anchor" href="#bild-12-demo-testa-det-allihopa-🌬️" aria-label="Permalink to &quot;Bild 12: DEMO - Testa det allihopa! 🌬️&quot;">​</a></h2><h3 id="_3-andetagsaterstallningsovning-1-minut" tabindex="-1">3-andetagsåterställningsövning (1 minut) <a class="header-anchor" href="#_3-andetagsaterstallningsovning-1-minut" aria-label="Permalink to &quot;3-andetagsåterställningsövning (1 minut)&quot;">​</a></h3><p><strong>Alla sluter ögonen...</strong></p><p><strong>Andlag 1:</strong><em>Andas in i 4... Var känner du spänning?</em></p><p><strong>Andlag 2:</strong><em>Andas ut i 6 sekunder... Släpp taget...</em></p><p><strong>Andning 3:</strong><em>In för 4, ut för 6... Bara nuet...</em></p><p><strong>Öppna dina ögon. Hur känner du dig?</strong></p><p><em>Detta är din återställningsknapp. Använd den!</em></p><hr><h2 id="bild-13-verktyg-2-din-rutin-fore-fotografering-🎯" tabindex="-1">Bild 13: Verktyg #2 - Din rutin före fotografering 🎯 <a class="header-anchor" href="#bild-13-verktyg-2-din-rutin-fore-fotografering-🎯" aria-label="Permalink to &quot;Bild 13: Verktyg #2 - Din rutin före fotografering 🎯&quot;">​</a></h2><h3 id="bygg-automatisk-konsekvens" tabindex="-1">Bygg automatisk konsekvens <a class="header-anchor" href="#bygg-automatisk-konsekvens" aria-label="Permalink to &quot;Bygg automatisk konsekvens&quot;">​</a></h3><p><strong>4-stegsrutinen:</strong></p><p><strong>1️⃣ VISUALISERA (3 sekunder)</strong> Se det perfekta skottet för dig. Se det landa exakt där du vill.</p><p><strong>2️⃣ ANDAS (2 sekunder)</strong> Ett djupt andetag. Växla från planerings- till utförandeläge.</p><p><strong>3️⃣ ANKRING (2 sekunder)</strong> Rör vid din boule. Känn tyngden. Fysisk kontakt.</p><p><strong>4️⃣ UTFÖR (2 sekunder)</strong> Lita helt och hållet på dig. Låt din kropp göra det den vet.</p><p><strong>⏱️ Totalt: 9 sekunder. Samma varje gång.</strong></p><h3 id="varfor-det-fungerar" tabindex="-1">Varför det fungerar: <a class="header-anchor" href="#varfor-det-fungerar" aria-label="Permalink to &quot;Varför det fungerar:&quot;">​</a></h3><p><strong>Konsekvens = Förtroende = Prestanda</strong></p><hr><h2 id="bild-14-verktyg-3-protokoll-for-felsokning-🔄" tabindex="-1">Bild 14: Verktyg #3 - Protokoll för felsökning 🔄 <a class="header-anchor" href="#bild-14-verktyg-3-protokoll-for-felsokning-🔄" aria-label="Permalink to &quot;Bild 14: Verktyg #3 - Protokoll för felsökning 🔄&quot;">​</a></h2><h3 id="daligt-skott-har-ar-din-aterhamtning-i-fyra-steg" tabindex="-1">Dåligt skott? Här är din återhämtning i fyra steg: <a class="header-anchor" href="#daligt-skott-har-ar-din-aterhamtning-i-fyra-steg" aria-label="Permalink to &quot;Dåligt skott? Här är din återhämtning i fyra steg:&quot;">​</a></h3><p><strong>1️⃣ BEKRÄFTELSE (2 sekunder)</strong> &quot;Det gick inte som planerat.&quot; (Ingen dömande blick, bara fakta)</p><p><strong>2️⃣ SLÄPP (3 sekunder)</strong> Fysisk återställning: Skaka händerna, rulla axlarna, gå 3 steg.</p><p><strong>3️⃣ OMFOKUSERA (3 sekunder)</strong> &quot;Nästa chans är en NY möjlighet.&quot; (Inte kopplad till den förra)</p><p><strong>4️⃣ UTFÖR (Använd din rutin)</strong> Lita på din rutin före sprutan. Nystart.</p><h3 id="den-viktigaste-insikten" tabindex="-1">Den viktigaste insikten: <a class="header-anchor" href="#den-viktigaste-insikten" aria-label="Permalink to &quot;Den viktigaste insikten:&quot;">​</a></h3><p><strong>Varje skott är oberoende. För inte misstag framåt.</strong></p><p><em>De bästa spelarna har kortast minne för dåliga skott.</em></p><hr><h2 id="bild-15-akta-prat-vad-hindrar-dig-💬" tabindex="-1">Bild 15: ÄKTA PRAT - Vad hindrar dig? 💬 <a class="header-anchor" href="#bild-15-akta-prat-vad-hindrar-dig-💬" aria-label="Permalink to &quot;Bild 15: ÄKTA PRAT - Vad hindrar dig? 💬&quot;">​</a></h2><h3 id="gruppdiskussion-5-minuter" tabindex="-1">Gruppdiskussion (5 minuter) <a class="header-anchor" href="#gruppdiskussion-5-minuter" aria-label="Permalink to &quot;Gruppdiskussion (5 minuter)&quot;">​</a></h3><p><strong>Låt oss höra från dig:</strong></p><p><strong>Fråga 1:</strong><em>&quot;När känner du dig som mest i flöde? Vilka tillstånd hjälper?&quot;</em></p><p><strong>Fråga 2:</strong><em>&quot;Vad är din största mentala utmaning i tävling?&quot;</em></p><p><strong>Fråga 3:</strong><em>&quot;Vilket av dessa verktyg resonerar mest med dig?&quot;</em></p><ul><li>3-andetagsåterställning</li><li>Rutin före skott</li><li>Inre coachens omformulering</li><li>Återställning av misstag</li></ul><p><strong>Dela öppet – detta är en trygg plats!</strong></p><hr><h2 id="bild-16-din-handlingsplan-valj-en-✅" tabindex="-1">Bild 16: Din handlingsplan - Välj EN! ✅ <a class="header-anchor" href="#bild-16-din-handlingsplan-valj-en-✅" aria-label="Permalink to &quot;Bild 16: Din handlingsplan - Välj EN! ✅&quot;">​</a></h2><h3 id="denna-veckas-utmaning" tabindex="-1">Denna veckas utmaning: <a class="header-anchor" href="#denna-veckas-utmaning" aria-label="Permalink to &quot;Denna veckas utmaning:&quot;">​</a></h3><p><strong>Välj ENDAST EN teknik att öva på:</strong></p><p><strong>Alternativ A: 🌬️ 3-Andetagsåterställning</strong> Använd efter VARJE misstag under träningen</p><p><strong>Alternativ B: 🎯 Förbehandlingsrutin</strong> Samma 4-stegsrutin på VARJE kast</p><p><strong>Alternativ C: 💬 Inre coach</strong> Omformulera EN kritisk tanke per session</p><p><strong>Alternativ D: 🔄 Lägesväxling</strong> Övningsplanering → utförandeomkopplare</p><h3 id="varfor-bara-en" tabindex="-1">Varför bara en? <a class="header-anchor" href="#varfor-bara-en" aria-label="Permalink to &quot;Varför bara en?&quot;">​</a></h3><p><strong>Bemästra ett verktyg innan du lägger till ett annat.</strong><em>Djup överträffar bredd i mental träning.</em></p><hr><h2 id="bild-17-folj-dina-framsteg-📊" tabindex="-1">Bild 17: Följ dina framsteg 📊 <a class="header-anchor" href="#bild-17-folj-dina-framsteg-📊" aria-label="Permalink to &quot;Bild 17: Följ dina framsteg 📊&quot;">​</a></h2><h3 id="vad-man-bor-lagga-marke-till-denna-vecka" tabindex="-1">Vad man bör lägga märke till denna vecka: <a class="header-anchor" href="#vad-man-bor-lagga-marke-till-denna-vecka" aria-label="Permalink to &quot;Vad man bör lägga märke till denna vecka:&quot;">​</a></h3><p><strong>🎯 Flödesögonblick:</strong></p><ul><li>När kände du dig &quot;i zonen&quot;?</li><li>Vilken tid på dygnet?</li><li>Vilken typ av skott?</li><li>Vad hjälpte dig att komma dit?</li></ul><p><strong>💪 Teknikframgång:</strong></p><ul><li>Vilket verktyg fungerade bäst?</li><li>När använde du den?</li><li>Vad blev resultatet?</li></ul><p><strong>📝 För en enkel loggbok:</strong><em>&quot;Använde 3-andetagsåterställning efter misstag → kände mig lugnare → tog nästa skott&quot;</em></p><h3 id="malet" tabindex="-1">Målet: <a class="header-anchor" href="#malet" aria-label="Permalink to &quot;Målet:&quot;">​</a></h3><p><strong>Hitta DINA mönster. Bygg DITT system.</strong></p><hr><h2 id="bild-18-fortsatt-din-resa-🚀" tabindex="-1">Bild 18: Fortsätt din resa 🚀 <a class="header-anchor" href="#bild-18-fortsatt-din-resa-🚀" aria-label="Permalink to &quot;Bild 18: Fortsätt din resa 🚀&quot;">​</a></h2><h3 id="gratis-resurser-pa-carreau-app" tabindex="-1">Gratis resurser på carreau.app: <a class="header-anchor" href="#gratis-resurser-pa-carreau-app" aria-label="Permalink to &quot;Gratis resurser på carreau.app:&quot;">​</a></h3><p><strong>📚 Djupdykning:</strong></p><ul><li><strong>Zonen</strong> - Huvudflödestillstånd</li><li><strong>Mental styrka</strong> - Avancerad presshantering</li><li><strong>Teamdynamik</strong> - Kommunikation och förtroende</li><li><strong>Mindfulness</strong> - Fokus i nuet</li></ul><p><strong>🛠️ Praktiska verktyg:</strong></p><ul><li><strong>Målmall</strong> - Strukturera din utveckling</li><li><strong>Dagboksmall</strong> - Följ dagliga framsteg</li><li><strong>Workshopguide</strong> - Håll dina egna sessioner</li></ul><p><strong>Allt gratis. Allt tillgängligt. Allt utformat för elitspelare.</strong></p><hr><h2 id="bild-19-de-4-stora-ideerna-💡" tabindex="-1">Bild 19: De 4 stora idéerna 💡 <a class="header-anchor" href="#bild-19-de-4-stora-ideerna-💡" aria-label="Permalink to &quot;Bild 19: De 4 stora idéerna 💡&quot;">​</a></h2><h3 id="ta-med-dessa-hem" tabindex="-1">Ta med dessa hem: <a class="header-anchor" href="#ta-med-dessa-hem" aria-label="Permalink to &quot;Ta med dessa hem:&quot;">​</a></h3><p><strong>1️⃣ Flöde är en FÄRDIGHET, inte tur</strong> Du kan lära dig att få tillgång till den på begäran</p><p><strong>2️⃣ Din inre röst FORMAR din prestation</strong> Coacha dig själv, kritisera inte dig själv</p><p><strong>3️⃣ Enkla verktyg ARBETAR under press</strong> 3 andetag. En rutin. En återställning. Det är allt.</p><p><strong>4️⃣ Övning ger beständighet</strong> Mentala färdigheter behöver träning, precis som tekniska färdigheter</p><h3 id="sanningen-1" tabindex="-1">Sanningen: <a class="header-anchor" href="#sanningen-1" aria-label="Permalink to &quot;Sanningen:&quot;">​</a></h3><p><strong>Mental träning är inte mystisk. Den är praktisk.</strong></p><hr><h2 id="bild-20-fragor-lat-oss-prata-💬" tabindex="-1">Bild 20: Frågor? Låt oss prata! 💬 <a class="header-anchor" href="#bild-20-fragor-lat-oss-prata-💬" aria-label="Permalink to &quot;Bild 20: Frågor? Låt oss prata! 💬&quot;">​</a></h2><h1 id="oppen-diskussion" tabindex="-1">Öppen diskussion <a class="header-anchor" href="#oppen-diskussion" aria-label="Permalink to &quot;Öppen diskussion&quot;">​</a></h1><p><strong>Vilka frågor har du?</strong></p><p><strong>Vilka erfarenheter vill du dela med dig av?</strong></p><p><strong>Vilka utmaningar står du inför?</strong></p><p><strong>Vad ska du prova först?</strong></p><p><em>Detta är DIN session. Låt oss göra den värdefull för DIG.</em></p><hr><h2 id="bild-21-din-utmaning-🎯" tabindex="-1">Bild 21: Din utmaning 🎯 <a class="header-anchor" href="#bild-21-din-utmaning-🎯" aria-label="Permalink to &quot;Bild 21: Din utmaning 🎯&quot;">​</a></h2><h1 id="denna-veckas-uppdrag" tabindex="-1">Denna veckas uppdrag: <a class="header-anchor" href="#denna-veckas-uppdrag" aria-label="Permalink to &quot;Denna veckas uppdrag:&quot;">​</a></h1><p><strong>1️⃣ Välj ETT verktyg</strong> (3-andetagsåterställning, förskottsrutin, inre tränare eller lägesväxling)</p><p><strong>2️⃣ Öva det VARJE session</strong> (Konsekvens överträffar intensitet)</p><p><strong>3️⃣ Lägg märke till vilka förändringar</strong> (Spåra dina framsteg)</p><p><strong>4️⃣ Dela dina resultat</strong> (Med dina träningspartners eller på carreau.app)</p><h3 id="komma-ihag" tabindex="-1">Komma ihåg: <a class="header-anchor" href="#komma-ihag" aria-label="Permalink to &quot;Komma ihåg:&quot;">​</a></h3><p><strong>Små förändringar → Stora resultat</strong></p><hr><h2 id="bild-22-tack-🙏" tabindex="-1">Bild 22: Tack! 🙏 <a class="header-anchor" href="#bild-22-tack-🙏" aria-label="Permalink to &quot;Bild 22: Tack! 🙏&quot;">​</a></h2><h1 id="du-har-koll-pa-det-har" tabindex="-1">Du har koll på det här! <a class="header-anchor" href="#du-har-koll-pa-det-har" aria-label="Permalink to &quot;Du har koll på det här!&quot;">​</a></h1><p><strong>Vad du lärde dig idag:</strong></p><ul><li>✅ Hur man får åtkomst till flödestillstånd</li><li>✅ Hur du hanterar din inre kritiker</li><li>✅ Praktiska verktyg som fungerar under press</li><li>✅ En tydlig handlingsplan för den här veckan</li></ul><p><strong>Nästa steg:</strong></p><ol><li>Välj din ENDA teknik</li><li>Öva det konsekvent</li><li>Besök carreau.app för fler resurser</li><li>Dela dina framsteg med gruppen</li></ol><h3 id="resan-borjar-nu" tabindex="-1">Resan börjar nu: <a class="header-anchor" href="#resan-borjar-nu" aria-label="Permalink to &quot;Resan börjar nu:&quot;">​</a></h3><p><strong>Mental träning är praktisk, inte mystisk.</strong><strong>Börja idag. Se resultat snart.</strong></p><hr><p><em>Pétanque Academy - Elite Player Development</em><em>carreau.app - Gratis resurser för elitspelare</em></p>',201)])])}]]);export{r as __pageData,i as default};
